101	// ---------------------------------------------------------------------------
102	// Folders
103	// ---------------------------------------------------------------------------
104	
105	/** List the mailbox's folders with unread/total counts and their role. */
106	export async function listFolders(mailboxAddress?: string): Promise<MailFolder[]> {
107	  const { cred } = await resolveMailbox(mailboxAddress);
108	  return withImap(cred, async (client) => {
109	    const list = await client.list({ statusQuery: { messages: true, unseen: true } });
110	    const folders: MailFolder[] = [];
111	    for (const f of list) {
112	      // Skip containers that can't hold messages.
113	      if (f.flags?.has("\\Noselect")) continue;
114	      folders.push({
115	        path: f.path,
116	        name: f.name || f.path,
117	        role: folderRole(f.path, f.specialUse),
118	        unread: f.status?.unseen ?? 0,
119	        total: f.status?.messages ?? 0,
120	      });
121	    }
122	    // Stable, useful ordering: known roles first, then custom alphabetically.
123	    const order: Record<string, number> = { inbox: 0, sent: 1, drafts: 2, archive: 3, junk: 4, trash: 5, custom: 6 };
124	    folders.sort((a, b) => (order[a.role] - order[b.role]) || a.name.localeCompare(b.name));
125	    return folders;
126	  });
127	}
