129	// ---------------------------------------------------------------------------
130	// Message list
131	// ---------------------------------------------------------------------------
132	
133	/** Decode a downloaded body part (transfer-encoding already decoded by server). */
134	function decodeCharset(buf: Buffer, charset?: string): string {
135	  const cs = (charset || "").toLowerCase();
136	  if (/latin1|8859|1252/.test(cs)) return buf.toString("latin1");
137	  return buf.toString("utf8");
138	}
139	
140	/** Fetch a short, transfer-decoded snippet of a message's text part for preview. */
141	async function fetchPreview(client: ImapFlow, uid: number, part: string): Promise<string> {
142	  try {
143	    const { meta, content } = await client.download(String(uid), part, { uid: true, maxBytes: 4096 });
144	    const chunks: Buffer[] = [];
145	    for await (const chunk of content) chunks.push(chunk as Buffer);
146	    return previewText(decodeCharset(Buffer.concat(chunks), meta.charset));
147	  } catch {
148	    return "";
149	  }
150	}
151	
152	/**
153	 * List a page of messages (newest first). `search` runs an IMAP SEARCH across
154	 * subject / from / to / body. Envelopes + a light body snippet only — never the
155	 * full body — so lists stay cheap.
156	 */
157	export async function listMessages(
158	  folder: string,
159	  page: number,
160	  search?: string,
161	  mailboxAddress?: string,
162	): Promise<ListResult> {
163	  const { cred } = await resolveMailbox(mailboxAddress);
164	  const pageNum = Math.max(1, Math.floor(page) || 1);
165	
166	  return withMailbox(
167	    cred,
168	    folder,
169	    async (client) => {
170	      const term = search?.trim();
171	      const query = term
172	        ? { or: [{ subject: term }, { from: term }, { to: term }, { body: term }] }
173	        : { all: true };
174	      const found = await client.search(query, { uid: true });
175	      const uids = (Array.isArray(found) ? found : []).slice().sort((a, b) => b - a); // newest first
176	
177	      const total = uids.length;
178	      const start = (pageNum - 1) * PAGE_SIZE;
179	      const pageUids = uids.slice(start, start + PAGE_SIZE);
180	      if (pageUids.length === 0) {
181	        return { messages: [], total, page: pageNum, pageSize: PAGE_SIZE };
182	      }
183	
184	      // 1) Cheap metadata pass for the page.
185	      const metaByUid = new Map<number, MessageSummary>();
186	      const previewPartByUid = new Map<number, string>();
187	      for await (const msg of client.fetch(
188	        pageUids,
189	        { uid: true, envelope: true, flags: true, internalDate: true, bodyStructure: true },
190	        { uid: true },
191	      )) {
192	        const flags = readFlags(msg.flags);
193	        const env = msg.envelope;
194	        metaByUid.set(msg.uid, {
195	          uid: msg.uid,
196	          folder,
197	          from: toMailAddress(env?.from?.[0]),
198	          to: toMailAddresses(env?.to),
199	          subject: env?.subject || "(no subject)",
200	          preview: "",
201	          date: isoDate(msg),
202	          seen: flags.seen,
203	          flagged: flags.flagged,
204	          answered: flags.answered,
205	          hasAttachments: structureHasAttachments(msg.bodyStructure),
206	        });
207	        previewPartByUid.set(msg.uid, findPreviewPart(msg.bodyStructure).part);
208	      }
209	
210	      // 2) Snippet pass (partial, PEEKed downloads — no flag changes).
211	      await Promise.all(
212	        pageUids.map(async (uid) => {
213	          const summary = metaByUid.get(uid);
214	          if (!summary) return;
215	          summary.preview = await fetchPreview(client, uid, previewPartByUid.get(uid) || "1");
216	        }),
217	      );
218	
219	      const messages = pageUids
220	        .map((uid) => metaByUid.get(uid))
221	        .filter((m): m is MessageSummary => Boolean(m));
222	      return { messages, total, page: pageNum, pageSize: PAGE_SIZE };
223	    },
224	    { readOnly: true },
225	  );
226	}
