286	// ---------------------------------------------------------------------------
287	// Sending
288	// ---------------------------------------------------------------------------
289	
290	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
291	
292	/** Parse a comma/semicolon-separated recipient string into validated addresses. */
293	function parseRecipients(input: string | undefined): { list: string[]; invalid: string[] } {
294	  const parts = (input || "")
295	    .split(/[,;]+/)
296	    .map((s) => s.trim())
297	    .filter(Boolean);
298	  const list: string[] = [];
299	  const invalid: string[] = [];
300	  for (const p of parts) {
301	    // Tolerate "Name <addr>" form by extracting the address.
302	    const m = p.match(/<([^>]+)>/);
303	    const addr = (m ? m[1] : p).trim();
304	    if (EMAIL_RE.test(addr)) list.push(addr);
305	    else invalid.push(p);
306	  }
307	  return { list, invalid };
308	}
309	
310	/** Resolve the IMAP path of the mailbox's Sent folder (defaults to "Sent"). */
311	async function findSentPath(client: ImapFlow): Promise<string> {
312	  try {
313	    const list = await client.list();
314	    const sent = list.find((f) => folderRole(f.path, f.specialUse) === "sent");
315	    return sent?.path || "Sent";
316	  } catch {
317	    return "Sent";
318	  }
319	}
320	
321	// Attachment limits — enforced server-side; never trust the client's own caps.
322	const MAX_ATTACHMENTS = 10;
323	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB decoded
324	
325	// Base64 inflates by ~4/3, so 20 MB of files arrives as ~26.7 MB of payload.
326	// `next.config.ts` raises `experimental.serverActions.bodySizeLimit` to 30 MB to
327	// match (Next's 1 MB default silently truncated anything over ~700 KB while both
328	// this file and the composer advertised 20 MB). This ceiling is the server-side
329	// half of that pairing: it rejects an over-large upload with a message the
330	// customer can act on, instead of letting Buffer.from allocate first.
331	const MAX_ATTACHMENTS_TOTAL_BASE64 = Math.ceil(MAX_ATTACHMENTS_TOTAL_BYTES / 3) * 4;
332	
333	/** Human-friendly byte size for limit messages (mirrors the composer's format). */
334	function fmtLimit(bytes: number): string {
335	  return `${Math.round(bytes / (1024 * 1024))} MB`;
336	}
337	
338	/** Strip path separators, quotes and control chars from an attachment filename. */
339	function sanitizeAttachmentName(name?: string): string {
340	  if (!name) return "";
341	  const cleaned = Array.from(name)
342	    .filter((ch) => {
343	      const c = ch.codePointAt(0) ?? 0;
344	      if (c < 0x20 || c === 0x7f) return false; // control chars
345	      if (ch === '"' || ch === "\\" || ch === "/") return false;
346	      return true;
347	    })
348	    .join("");
349	  return cleaned.trim().slice(0, 200);
350	}
351	
352	type BuiltAttachment = { filename: string; content: Buffer; contentType: string; cid?: string };
353	
354	/**
355	 * Validate + decode client-supplied attachments. Caps count and total decoded
356	 * size, validates base64, sanitises filenames and defaults the content type.
357	 * Returns the decoded buffers or a friendly error string.
358	 */
359	function decodeAttachments(
360	  input: SendAttachment[] | undefined,
361	): { ok: true; attachments: BuiltAttachment[] } | { ok: false; error: string } {
362	  if (!input || input.length === 0) return { ok: true, attachments: [] };
363	  if (!Array.isArray(input)) return { ok: false, error: "Invalid attachments." };
364	  if (input.length > MAX_ATTACHMENTS) {
365	    return { ok: false, error: `Too many attachments — up to ${MAX_ATTACHMENTS} allowed.` };
366	  }
367	
368	  // Reject on the ENCODED length before decoding anything, so an oversize upload
369	  // fails with a clear message rather than being decoded into memory first.
370	  let encodedTotal = 0;
371	  for (const a of input) {
372	    if (a && typeof a.contentBase64 === "string") encodedTotal += a.contentBase64.length;
373	  }
374	  if (encodedTotal > MAX_ATTACHMENTS_TOTAL_BASE64) {
375	    return {
376	      ok: false,
377	      error: `Attachments are too large — the total must be under ${fmtLimit(MAX_ATTACHMENTS_TOTAL_BYTES)}. Remove a file or send it as a link.`,
378	    };
379	  }
380	
381	  const out: BuiltAttachment[] = [];
382	  let total = 0;
383	  for (let i = 0; i < input.length; i++) {
384	    const a = input[i];
385	    if (!a || typeof a.contentBase64 !== "string") {
386	      return { ok: false, error: "Invalid attachment data." };
387	    }
388	    // Tolerate a stray "data:*;base64," prefix, then validate the base64.
389	    const b64 = a.contentBase64.replace(/^data:[^;]*;base64,/, "").trim();
390	    if (!/^[A-Za-z0-9+/]*={0,2}$/.test(b64) || b64.length % 4 !== 0) {
391	      return { ok: false, error: "Attachment could not be read (invalid encoding)." };
392	    }
393	    const content = Buffer.from(b64, "base64");
394	    total += content.length;
395	    if (total > MAX_ATTACHMENTS_TOTAL_BYTES) {
396	      return {
397	        ok: false,
398	        error: `Attachments exceed the ${fmtLimit(MAX_ATTACHMENTS_TOTAL_BYTES)} total limit.`,
399	      };
400	    }
401	    const filename = sanitizeAttachmentName(a.filename) || `attachment-${i + 1}`;
402	    const contentType =
403	      typeof a.contentType === "string" && a.contentType.trim()
404	        ? a.contentType.trim().slice(0, 128)
405	        : "application/octet-stream";
406	    // Inline images carry a Content-ID the HTML body references as `cid:<cid>`.
407	    // Constrain it to a sane token so it can't inject header syntax.
408	    const cid =
409	      typeof a.cid === "string" && /^[A-Za-z0-9._@+-]{1,120}$/.test(a.cid) ? a.cid : undefined;
410	    out.push({ filename, content, contentType, cid });
411	  }
412	  return { ok: true, attachments: out };
413	}
414	
415	/**
416	 * Send a message from the user's own mailbox over SMTP submission, append a copy
417	 * to Sent, and (for replies) thread it + flag the original \Answered.
418	 */
419	export async function sendMessage(
420	  payload: SendPayload,
421	  mailboxAddress?: string,
422	): Promise<{ ok: boolean; error?: string }> {
423	  const { user, cred, identity } = await resolveMailbox(mailboxAddress);
424	  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
425	  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });
426	
427	  const to = parseRecipients(payload.to);
428	  const cc = parseRecipients(payload.cc);
429	  const bcc = parseRecipients(payload.bcc);
430	  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
431	  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
432	  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
433	  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
434	    return { ok: false, error: "Nothing to send — add a subject or a message." };
435	  }
436	
437	  const decoded = decodeAttachments(payload.attachments);
438	  if (!decoded.ok) return { ok: false, error: decoded.error };
439	  const attachments = decoded.attachments;
440	
441	  try {
442	    // Look up threading headers when this is a reply.
443	    let inReplyTo: string | undefined;
444	    let references: string | undefined;
445	    if (payload.inReplyToUid && payload.replyFolder) {
446	      try {
447	        await withMailbox(cred, payload.replyFolder, async (client) => {
448	          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
449	          if (orig && orig.envelope?.messageId) {
450	            inReplyTo = orig.envelope.messageId;
451	            references = orig.envelope.messageId;
452	          }
453	          // Mark the message we're replying to as answered (best effort).
454	          try {
455	            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
456	          } catch {
457	            /* ignore */
458	          }
459	        });
460	      } catch {
461	        /* original not found — send without threading headers */
462	      }
463	    }
464	
465	    // Apply the saved sender identity.
466	    //
467	    // These three columns were written by the Identity panel and read by NOTHING:
468	    // the panel promised "Shown as the sender name on messages you send" and every
469	    // message still went out bare `from: cred.address` with no Reply-To, so a
470	    // customer who set a reply-to address had replies quietly go to the wrong
471	    // mailbox. Each field falls back to the previous behaviour when unset.
472	    //
473	    // Note `from` only changes the HEADER. nodemailer derives `built.envelope`
474	    // from the address part, so SMTP MAIL FROM stays the authenticated mailbox
475	    // and SPF/DKIM alignment (fixed today) is untouched.
476	    const displayName = identity.displayName?.trim();
477	    const replyTo = identity.replyTo?.trim();
478	    const organization = identity.organization?.trim();
479	
480	    // SANITISE the composed HTML server-side before it ships. The composer
481	    // already runs `safeHtml`, but this action is the last gate a body passes
482	    // through and must never trust the client — so an XSS vector or a malformed
483	    // body can't reach a recipient even if the client is bypassed. `safeHtml`
484	    // preserves `cid:` image refs and inline formatting; it only strips scripts,
485	    // event handlers and dangerous URL schemes.
486	    const safeBodyHtml = payload.html ? safeHtml(payload.html) : undefined;
487	
488	    // Map decoded attachments to nodemailer's shape, marking inline images
489	    // (those with a cid) so clients render them in place via multipart/related.
490	    const mailAttachments = attachments.map((a) =>
491	      a.cid
492	        ? { filename: a.filename, content: a.content, contentType: a.contentType, cid: a.cid, contentDisposition: "inline" as const }
493	        : { filename: a.filename, content: a.content, contentType: a.contentType },
494	    );
495	
496	    // Compile the message once so the exact bytes are both sent and saved to Sent.
497	    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
498	    const built = await composer.sendMail({
499	      from: displayName ? { name: displayName, address: cred.address } : cred.address,
500	      replyTo: replyTo || undefined,
501	      to: to.list,
502	      cc: cc.list.length ? cc.list : undefined,
503	      bcc: bcc.list.length ? bcc.list : undefined,
504	      subject: payload.subject || "",
505	      text: payload.text || undefined,
506	      html: safeBodyHtml,
507	      attachments: mailAttachments.length ? mailAttachments : undefined,
508	      inReplyTo,
509	      references,
510	      headers: organization ? { Organization: organization } : undefined,
511	    });
512	    const raw = built.message as Buffer;
513	
514	    const smtp = nodemailer.createTransport({
515	      host: MAIL_SMTP_HOST,
516	      port: MAIL_SMTP_PORT,
517	      secure: MAIL_SMTP_PORT === 465,
518	      requireTLS: MAIL_SMTP_PORT !== 465,
519	      // Certificate verification stays ON — this session carries the customer's
520	      // mailbox password. See `mailTlsOptions` for the measurement behind it.
521	      tls: mailTlsOptions(),
522	      auth: { user: cred.address, pass: cred.password },
523	    });
524	    await smtp.sendMail({ envelope: built.envelope, raw });
525	
526	    // Save a copy to Sent (best effort — the message already went out).
527	    try {
528	      await withImap(cred, async (client) => {
529	        const sentPath = await findSentPath(client);
530	        await client.append(sentPath, raw, ["\\Seen"]);
531	      });
532	    } catch {
533	      /* Sent append failed — not fatal */
534	    }
535	
536	    return { ok: true };
537	  } catch (e) {
538	    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
539	  }
540	}
541	
542	// ---------------------------------------------------------------------------
543	// Flags / move / delete
544	// ---------------------------------------------------------------------------
545	
546	/** Set or clear the \Seen or \Flagged flag on a message. */
547	export async function setFlag(
548	  folder: string,
549	  uid: number,
550	  flag: "seen" | "flagged",
551	  value: boolean,
552	  mailboxAddress?: string,
553	): Promise<void> {
554	  const { user, cred } = await resolveMailbox(mailboxAddress);
555	  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
556	  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
557	  await withMailbox(cred, folder, async (client) => {
558	    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
559	    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
560	  });
561	}
