1	// Sieve compiler for the customer-facing mailbox rules (auto-reply + forwarding).
2	//
3	// Plain server-side module (NO "use server"): pure string building, no I/O. The
4	// caller (lib/actions-mailbox-settings.ts) pushes the result to Mailcow.
5	//
6	// WHY this file exists: auto-reply and forwarding were STORE-ONLY. The panel
7	// said "saved", nothing on the mail server changed, and a customer who switched
8	// on an out-of-office before a holiday got no auto-replies and no forwarded mail
9	// at all. Mailcow's REST API does expose per-mailbox sieve filters, so the rules
10	// can be made real.
11	//
12	// WHAT IS ACTUALLY VERIFIED — and what is not. Be precise here, because a
13	// confident but unchecked claim is this codebase's recurring defect:
14	//
15	//   VERIFIED (read-only, against the live server, 2026-07-26):
16	//     `GET /get/filters/<address>` and `GET /get/filters/all` answer HTTP 200
17	//     with `{}` (no filters exist yet), while a nonexistent route answers HTTP
18	//     404 `{"type":"error","msg":"route not found"}`. So the filter API is real
19	//     on this instance even though it is absent from Mailcow's published
20	//     openapi.yaml (which documents no /filter route and never mentions sieve).
21	//
22	//   NOT VERIFIED: the write side. `POST /add|edit|delete/filter` cannot be
23	//     exercised without mutating a live mail server, and Dovecot's
24	//     `sieve_extensions` list is not readable from the portal host (managesieve
25	//     on 4190 is not reachable from here). `vacation`, `copy`, `date` and
26	//     `relational` are Pigeonhole defaults and are in mailcow's own PHP sieve
27	//     validator, but that is inference, not a measurement.
28	//
29	// This is SAFE to ship unverified only because of how the caller fails: mailcow's
30	// validator rejects the entire API call if a `require` names an extension it
31	// does not know, `mcRequest` turns that into a thrown MailcowError, and
32	// lib/actions-mailbox-settings.ts pushes to Mailcow BEFORE writing the DB and
33	// returns the error without persisting. A wrong guess therefore surfaces as
34	// "couldn't apply this on the mail server" — never as the silent "Saved" that
35	// this replaces. Keep that ordering.
36	//
37	// Everything is compiled into ONE script because Mailcow keeps at most one
38	// ACTIVE filter per (mailbox, filter_type) — adding a second active filter
39	// silently deactivates the first, which would make enabling forwarding turn the
40	// customer's auto-reply back off.
41	
42	/** The rule state we compile from — the persisted Mailbox columns, verbatim. */
43	export type MailboxRuleState = {
44	  address: string;
45	  autoReplyEnabled: boolean;
46	  autoReplySubject: string | null;
47	  autoReplyBody: string | null;
48	  autoReplyStart: Date | null;
49	  autoReplyEnd: Date | null;
50	  forwardingAddress: string | null;
51	  forwardKeepCopy: boolean;
52	};
53	
54	/**
55	 * `script_desc` we tag our filter with. This is the ONLY thing that identifies a
56	 * script as ours, so the sync path never edits or deletes a filter a customer
57	 * (or an operator) created by hand in Mailcow's own UI.
58	 */
59	export const NXEON_SIEVE_DESC = "Nxeon mailbox settings (managed — do not edit)";
60	
61	/**
62	 * Mailcow's `prefilter` maps to Dovecot `sieve_before`, so these rules run ahead
63	 * of the mailbox's own personal script. Forwarding and out-of-office must not be
64	 * defeated by a later "file everything into a folder" rule.
65	 */
66	export const NXEON_SIEVE_TYPE = "prefilter" as const;
67	
68	// Markers so the live script can be read back and reported honestly in the UI
69	// without re-parsing sieve. `getMailRuleStatus` looks for exactly these.
70	export const MARK_AUTOREPLY = "# nxeon:autoreply";
71	export const MARK_FORWARD = "# nxeon:forward";
72	
73	/**
74	 * Quote a value as a sieve quoted-string (RFC 5228 §2.4.2).
75	 *
76	 * Backslash first, then the quote character — reversing the order would
77	 * double-escape. Control characters are dropped rather than escaped: sieve has
78	 * no escape form for them, and a stray NUL or ESC in the body would make
79	 * Mailcow's validator reject the entire save. CRLF is legal inside a quoted
80	 * string, so multi-line auto-reply bodies survive intact.
81	 */
82	function sq(value: string): string {
83	  const cleaned = value
84	    // eslint-disable-next-line no-control-regex
85	    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "")
86	    .replace(/\r\n|\r|\n/g, "\n");
87	  const escaped = cleaned.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\r\n");
88	  return `"${escaped}"`;
89	}
90	
91	/** Format a Date as the `YYYY-MM-DD` string sieve's `date`/`"date"` part yields. */
92	function isoDay(d: Date): string {
93	  return d.toISOString().slice(0, 10);
94	}
95	
96	/**
97	 * Compile the mailbox's rules into a sieve script, or return "" when the
98	 * customer has nothing enabled (the caller then DELETES the managed filter, so
99	 * turning a rule off really turns it off on the server).
100	 */
101	export function buildMailboxSieve(state: MailboxRuleState): string {
102	  const requires = new Set<string>();
103	  const body: string[] = [];
104	
105	  const autoReplyBody = (state.autoReplyBody ?? "").trim();
106	  const autoReplyOn = state.autoReplyEnabled && autoReplyBody.length > 0;
107	  const forwardTo = (state.forwardingAddress ?? "").trim().toLowerCase();
108	  const forwardOn = forwardTo.length > 0;
109	
110	  if (autoReplyOn) {
111	    requires.add("vacation");
112	
113	    // `:days 1` is Pigeonhole's dedupe window: one auto-reply per sender per day,
114	    // so a mailing list or a retrying sender can't be answered in a loop.
115	    const args = [":days 1", `:addresses [${sq(state.address)}]`];
116	    const subject = (state.autoReplySubject ?? "").trim();
117	    // An empty `:subject` is invalid; omitting it lets Pigeonhole use
118	    // "Auto: <original subject>", which is better than a blank Subject header.
119	    if (subject) args.push(`:subject ${sq(subject)}`);
120	    const vacation = `vacation ${args.join(" ")} ${sq(autoReplyBody)};`;
121	
122	    // The date window is enforced ON THE SERVER, not by us flipping a flag on a
123	    // schedule — nothing in this codebase runs a job to re-push sieve at
124	    // midnight, so a client-side window would have kept replying forever.
125	    const guards: string[] = [];
126	    if (state.autoReplyStart) guards.push(`currentdate :value "ge" "date" ${sq(isoDay(state.autoReplyStart))}`);
127	    if (state.autoReplyEnd) guards.push(`currentdate :value "le" "date" ${sq(isoDay(state.autoReplyEnd))}`);
128	
129	    body.push(MARK_AUTOREPLY);
130	    if (guards.length === 0) {
131	      body.push(vacation);
132	    } else {
133	      requires.add("date");
134	      requires.add("relational");
135	      // Kept on one line on purpose: the script is joined with CRLF below, so an
136	      // embedded "\n" here would leave a bare LF in the middle of a statement.
137	      const test = guards.length === 1 ? guards[0] : `allof (${guards.join(", ")})`;
138	      body.push(`if ${test}`, "{", `  ${vacation}`, "}");
139	    }
140	  }
141	
142	  if (forwardOn) {
143	    body.push("", MARK_FORWARD);
144	    if (state.forwardKeepCopy) {
145	      // `redirect :copy` leaves the implicit keep intact, so the message is both
146	      // forwarded and delivered here.
147	      requires.add("copy");
148	      body.push(`redirect :copy ${sq(forwardTo)};`);
149	    } else {
150	      // A bare `redirect` cancels the implicit keep; `stop` ends the script chain
151	      // so no later script in the sequence can re-introduce a local delivery.
152	      body.push(`redirect ${sq(forwardTo)};`, "stop;");
153	    }
154	  }
155	
156	  if (body.length === 0) return "";
157	
158	  const header = [
159	    "# Generated by Nxeon from your mailbox settings. Changes here are overwritten.",
160	    `# Mailbox: ${state.address.replace(/[\r\n]/g, "")}`,
161	  ];
162	  const requireLine =
163	    requires.size > 0 ? `require [${[...requires].sort().map((r) => sq(r)).join(", ")}];` : "";
164	
165	  return [...header, requireLine, "", ...body]
166	    .filter((line, i, all) => !(line === "" && all[i - 1] === "")) // no double blanks
167	    .join("\r\n")
168	    .concat("\r\n");
169	}
170	
171	/** True when the live script on the server is one we generated. */
172	export function isNxeonSieve(scriptDesc: string): boolean {
173	  return scriptDesc.trim() === NXEON_SIEVE_DESC;
174	}
