393	/**
394	 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
395	 * logout, falling back to a hard close). Suitable for one operation per request.
396	 */
397	export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
398	  const client = createImapClient(cred);
399	  await client.connect();
400	  try {
401	    return await fn(client);
402	  } finally {
403	    try {
404	      await client.logout();
405	    } catch {
406	      try {
407	        client.close();
408	      } catch {
409	        /* already gone */
410	      }
411	    }
412	  }
413	}
