415	/**
416	 * Like `withImap` but also selects `path` under a mailbox lock (released before
417	 * the connection closes). Use for any op that fetches/searches/mutates messages.
418	 */
419	export async function withMailbox<T>(
420	  cred: MailboxCredentials,
421	  path: string,
422	  fn: (client: ImapFlow) => Promise<T>,
423	  opts?: { readOnly?: boolean },
424	): Promise<T> {
425	  return withImap(cred, async (client) => {
426	    const lockOpts: MailboxLockOptions = { readOnly: opts?.readOnly };
427	    const lock = await client.getMailboxLock(path, lockOpts);
428	    try {
429	      return await fn(client);
430	    } finally {
431	      lock.release();
432	    }
433	  });
434	}
