474	/**
475	 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
476	 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
477	 * "1" for a simple single-part message (whose structure carries no part id).
478	 */
479	export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
480	  if (!structure) return { part: "1", isHtml: false };
481	  const leaves: MessageStructureObject[] = [];
482	  const walk = (node: MessageStructureObject) => {
483	    if (node.childNodes && node.childNodes.length) {
484	      node.childNodes.forEach(walk);
485	    } else {
486	      leaves.push(node);
487	    }
488	  };
489	  walk(structure);
490	
491	  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
492	  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
493	  if (plain) return { part: plain.part || "1", isHtml: false };
494	  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
495	  if (html) return { part: html.part || "1", isHtml: true };
496	  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
497	}
498	
499	/** True if a BODYSTRUCTURE tree contains at least one attachment-like part. */
500	export function structureHasAttachments(structure: MessageStructureObject | undefined): boolean {
501	  if (!structure) return false;
502	  let found = false;
503	  const walk = (node: MessageStructureObject) => {
504	    const type = (node.type || "").toLowerCase();
505	    const disp = (node.disposition || "").toLowerCase();
506	    if (node.childNodes && node.childNodes.length) {
507	      node.childNodes.forEach(walk);
508	      return;
509	    }
510	    if (disp === "attachment") found = true;
511	    else if (!type.startsWith("text/") && !type.startsWith("multipart/")) found = true;
512	  };
513	  walk(structure);
514	  return found;
515	}
