241	
242	  if (input.signatureHtml !== undefined) {
243	    const clean = safeHtml(input.signatureHtml);
244	    if (clean.length > SIGNATURE_HTML_MAX) {
245	      return { ok: false, error: "Signature is too long. Please shorten it." };
246	    }
247	    data.signatureHtml = clean || null;
248	    const plain = signatureHtmlToText(clean);
249	    data.signature = plain ? plain : null;
250	  }
251	
252	  if (input.signatureEnabled !== undefined) data.signatureEnabled = Boolean(input.signatureEnabled);
253	  if (input.signatureOnReply !== undefined) data.signatureOnReply = Boolean(input.signatureOnReply);
254	  if (input.signaturePlacement !== undefined) {
255	    data.signaturePlacement = input.signaturePlacement === "above" ? "above" : "below";
256	  }
257	
258	  if (Object.keys(data).length > 0) {
259	    await updateMailboxRow(mailboxId, data);
260	  }
261	  return { ok: true };
262	}
263	
264	// ---------------------------------------------------------------------------
265	// Server-side rules: auto-reply + forwarding, as real Mailcow sieve filters
266	// ---------------------------------------------------------------------------
267	//
268	// These two were STORE-ONLY: the panel wrote the DB, showed a green "Saved",
269	// and NOTHING on the mail server changed. A customer switching on an
270	// out-of-office before a holiday got no auto-replies and no forwarded mail. The
271	// old comments claimed the API had no primitive for this; it does —
272	// `POST /add|edit|delete/filter` drives Dovecot sieve per mailbox (see
273	// lib/mail/sieve.ts for the capability audit).
274	//
275	// The whole rule set is compiled into ONE managed script and pushed BEFORE the
276	// DB is written, so the stored preference and the live server never disagree.
277	// If Mailcow rejects the push the DB is left untouched and the customer sees the
278	// failure — the opposite of the "Saved" lie this replaces.
279	
280	/** Live state of the managed sieve script, read back from the mail server. */
281	export type MailRuleStatus = {
282	  /** Rules can be enforced at all (Mailcow configured + reachable + domain verified). */
283	  supported: boolean;
284	  /** The server is currently running our auto-reply / forwarding rule. */
285	  autoReplyLive: boolean;
286	  forwardingLive: boolean;
287	  /** Why enforcement is unavailable, when it is. */
288	  error?: string;
289	};
290	
291	/** Load the rule columns for a mailbox we have already ownership-checked. */
292	async function ruleState(mailboxId: string, address: string): Promise<MailboxRuleState> {
293	  const row = await loadMailboxRow(mailboxId);
294	  return {
295	    address,
296	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
297	    autoReplySubject: row?.autoReplySubject ?? null,
298	    autoReplyBody: row?.autoReplyBody ?? null,
299	    autoReplyStart: row?.autoReplyStart ?? null,
300	    autoReplyEnd: row?.autoReplyEnd ?? null,
301	    forwardingAddress: row?.forwardingAddress ?? null,
302	    forwardKeepCopy: row?.forwardKeepCopy ?? true,
303	  };
304	}
305	
306	/**
307	 * Push `state` to Mailcow as the mailbox's single managed sieve filter.
308	 *
309	 * Idempotent: reuses our existing filter when there is one, prunes duplicates
310	 * left by an interrupted save, and DELETES the filter when nothing is enabled so
311	 * switching a rule off really switches it off on the server.
312	 *
313	 * Only ever touches a filter whose `script_desc` is ours — a filter an operator
314	 * created by hand in Mailcow's own UI is left completely alone.
315	 *
316	 * Throws on failure; callers translate that into a user-visible error and skip
317	 * the DB write.
318	 */
319	async function pushMailboxSieve(state: MailboxRuleState): Promise<void> {
320	  const script = buildMailboxSieve(state);
321	  const existing = (await mcListFilters(state.address)).filter((f) => isNxeonSieve(f.scriptDesc));
322	
323	  if (!script) {
324	    for (const f of existing) await mcDeleteFilter(f.id);
325	    return;
326	  }
327	
328	  const [keep, ...duplicates] = existing;
329	  for (const f of duplicates) await mcDeleteFilter(f.id);
330	
331	  if (keep) {
332	    await mcEditFilter(keep.id, {
333	      scriptDesc: NXEON_SIEVE_DESC,
334	      scriptData: script,
335	      filterType: NXEON_SIEVE_TYPE,
336	      active: true,
337	    });
338	  } else {
339	    await mcAddFilter({
340	      address: state.address,
341	      scriptDesc: NXEON_SIEVE_DESC,
342	      scriptData: script,
343	      filterType: NXEON_SIEVE_TYPE,
344	      active: true,
345	    });
346	  }
347	}
348	
349	/**
350	 * Guard shared by both rule savers.
351	 *
352	 * A sieve `redirect` sends a copy of every inbound message somewhere else, so
353	 * this is exactly the primitive a cross-tenant takeover would want. Owning the
354	 * subscription ROW is not proof of owning the DOMAIN (the 2026-07-25 finding),
355	 * so an unverified external domain is refused outright.
356	 */
357	function assertRulesAllowed(sub: {
358	  external: boolean;
359	  verified: boolean;
360	  status: string;
361	}): { ok: false; error: string } | null {
362	  if (!mailcowConfigured()) {
363	    return { ok: false, error: "Mail server is not configured yet — rules can't be applied." };
364	  }
365	  if (sub.status === "CANCELLED") {
366	    return { ok: false, error: "This subscription is cancelled." };
367	  }
368	  if (sub.external && !sub.verified) {
369	    return {
370	      ok: false,
371	      error: "Verify this domain first (Business Email → Verify DNS) before setting up mail rules.",
372	    };
373	  }
374	  return null;
375	}
376	
377	/**
378	 * Report what the mail server is ACTUALLY running, so the panel can stop
379	 * guessing. Derived from the live script's markers, not from the DB — if a rule
380	 * was never applied (or was removed on the server) this says so.
381	 */
382	export async function getMailRuleStatus(mailboxAddress?: string): Promise<MailRuleStatus> {
383	  const { address, subscription } = await resolveMailbox(mailboxAddress);
384	  const blocked = assertRulesAllowed(subscription);
385	  if (blocked) return { supported: false, autoReplyLive: false, forwardingLive: false, error: blocked.error };
386	
387	  try {
388	    const mine = (await mcListFilters(address)).find((f) => isNxeonSieve(f.scriptDesc) && f.active);
389	    return {
390	      supported: true,
391	      autoReplyLive: Boolean(mine?.scriptData.includes(MARK_AUTOREPLY)),
392	      forwardingLive: Boolean(mine?.scriptData.includes(MARK_FORWARD)),
393	    };
394	  } catch (e) {
395	    return {
396	      supported: false,
397	      autoReplyLive: false,
398	      forwardingLive: false,
399	      error: `Couldn't reach the mail server to read your rules: ${friendly(e)}`,
400	    };
401	  }
402	}
403	
404	/**
405	 * Forward inbound mail to another address, enforced by a real sieve `redirect`.
406	 * "Keep a copy" maps to `redirect :copy` (implicit keep survives); without it a
407	 * bare `redirect` + `stop` forwards without local delivery.
408	 */
409	export async function saveForwarding(
410	  input: { enabled: boolean; address?: string; keepCopy?: boolean },
411	  mailboxAddress?: string,
412	): Promise<Result> {
413	  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
414	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
415	  if (limited) return limited;
416	
417	  const enabled = Boolean(input.enabled);
418	  const target = (input.address ?? "").trim().toLowerCase();
419	  const keepCopy = input.keepCopy !== false;
420	
421	  if (enabled) {
422	    if (!target) return { ok: false, error: "Enter an address to forward to." };
423	    if (!EMAIL_RE.test(target)) return { ok: false, error: "That doesn't look like a valid email address." };
424	    if (target.length > 200) return { ok: false, error: "That address is too long." };
425	    if (target === address.toLowerCase()) return { ok: false, error: "Forwarding to this mailbox itself does nothing." };
426	  }
427	
428	  const blocked = assertRulesAllowed(subscription);
429	  if (blocked) return blocked;
430	
431	  const next: MailboxRuleState = {
432	    ...(await ruleState(mailboxId, address)),
433	    forwardingAddress: enabled && target ? target : null,
434	    forwardKeepCopy: keepCopy,
435	  };
436	
437	  try {
438	    await pushMailboxSieve(next);
439	  } catch (e) {
440	    // Deliberately do NOT persist: a stored "forwarding on" that the server is
441	    // not running is the exact defect this replaces.
442	    return { ok: false, error: `Couldn't apply forwarding on the mail server: ${friendly(e)}` };
443	  }
444	
445	  await updateMailboxRow(mailboxId, {
446	    forwardingAddress: next.forwardingAddress,
447	    forwardKeepCopy: next.forwardKeepCopy,
448	  });
449	
450	  await db.auditLog
451	    .create({
452	      data: {
453	        userId: user.id,
454	        action: "mailbox.forwarding",
455	        detail: `${address} → ${next.forwardingAddress ?? "off"}${next.forwardingAddress && !keepCopy ? " (no local copy)" : ""}`,
456	      },
457	    })
458	    .catch(() => {});
459	
460	  return { ok: true };
461	}
462	
463	/**
464	 * Out-of-office responder, enforced by a real sieve `vacation`. The date window
465	 * is compiled into the script as a `currentdate` test so the mail server starts
466	 * and stops replying on its own — nothing here runs on a schedule, so a window
467	 * evaluated in this process would simply never stop.
468	 */
469	export async function saveAutoReply(
470	  input: { enabled: boolean; subject?: string; body?: string; start?: string | null; end?: string | null },
471	  mailboxAddress?: string,
472	): Promise<Result> {
473	  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
474	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
475	  if (limited) return limited;
476	
477	  const enabled = Boolean(input.enabled);
478	  const subject = (input.subject ?? "").trim();
479	  const body = (input.body ?? "").trim();
480	  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
481	  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
482	  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };
483	
484	  const start = fromDateInput(input.start);
485	  const end = fromDateInput(input.end);
486	  if (start && end && start.getTime() > end.getTime()) {
487	    return { ok: false, error: "The start date must be on or before the end date." };
488	  }
489	
490	  const blocked = assertRulesAllowed(subscription);
491	  if (blocked) return blocked;
492	
493	  const next: MailboxRuleState = {
494	    ...(await ruleState(mailboxId, address)),
495	    autoReplyEnabled: enabled,
496	    autoReplySubject: subject || null,
497	    autoReplyBody: body || null,
498	    autoReplyStart: start,
499	    autoReplyEnd: end,
500	  };
501	
502	  try {
503	    await pushMailboxSieve(next);
504	  } catch (e) {
505	    return { ok: false, error: `Couldn't apply the auto-reply on the mail server: ${friendly(e)}` };
506	  }
507	
508	  await updateMailboxRow(mailboxId, {
509	    autoReplyEnabled: next.autoReplyEnabled,
510	    autoReplySubject: next.autoReplySubject,
511	    autoReplyBody: next.autoReplyBody,
512	    autoReplyStart: next.autoReplyStart,
513	    autoReplyEnd: next.autoReplyEnd,
514	  });
515	
516	  await db.auditLog
517	    .create({
518	      data: {
519	        userId: user.id,
520	        action: "mailbox.autoreply",
521	        detail: `${address} → ${enabled ? "on" : "off"}`,
522	      },
523	    })
524	    .catch(() => {});
525	
526	  return { ok: true };
527	}
