250	/** Renders the email body. HTML is dropped into a sandboxed iframe with
251	 *  `allow-same-origin` but crucially NO `allow-scripts`, so sender scripts still
252	 *  never execute — allow-same-origin only lets the PARENT read the inner document
253	 *  to auto-size the frame to its full content height. Plaintext falls back to a
254	 *  pre block. */
255	function MessageBody({ html, text }: { html: string | null; text: string | null }) {
256	  const ref = useRef<HTMLIFrameElement>(null);
257	  const observerRef = useRef<ResizeObserver | null>(null);
258	  const [height, setHeight] = useState(MIN_BODY_HEIGHT);
259	
260	  const doc = html
261	    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
262	        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
263	        body{padding:16px;}
264	        img{max-width:100%;height:auto;}
265	        a{color:#5f2ee8;}
266	        table{max-width:100%;}
267	        pre{white-space:pre-wrap;}
268	        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
269	      </style></head><body>${html}</body></html>`
270	    : null;
271	
272	  // Autosize: with sandbox="allow-same-origin" (and still NO allow-scripts, so
273	  // sender scripts stay inert) the parent can read the inner document and grow the
274	  // frame to its full content height — the whole email renders in the page flow
275	  // (the reading pane scrolls, the frame itself never does), so tall mail is no
276	  // longer clipped. Reset to the min height when the body changes.
277	  useEffect(() => {
278	    setHeight(html ? MIN_BODY_HEIGHT : 0);
279	  }, [html]);
280	
281	  // Measure the rendered document and size the frame to it (plus a small buffer),
282	  // clamped so short mail isn't a giant box and runaway content can't explode.
283	  const measure = useCallback(() => {
284	    const cdoc = ref.current?.contentDocument;
285	    if (!cdoc) return;
286	    const h = Math.max(
287	      cdoc.documentElement?.scrollHeight ?? 0,
288	      cdoc.body?.scrollHeight ?? 0,
289	    );
290	    if (h > 0) {
291	      setHeight(Math.min(MAX_BODY_HEIGHT, Math.max(MIN_BODY_HEIGHT, Math.ceil(h) + BODY_HEIGHT_BUFFER)));
292	    }
293	  }, []);
294	
295	  // Tear down the body observer on unmount / body swap.
296	  useEffect(() => () => { observerRef.current?.disconnect(); observerRef.current = null; }, []);
297	
298	  // On each (re)load: measure once, then keep re-measuring as late layout settles
299	  // — image decode, web-font swaps, async reflows. A ResizeObserver on the inner
300	  // <body> catches most of it; a few delayed passes and per-image load handlers
301	  // cover the rest.
302	  const handleLoad = useCallback(() => {
303	    measure();
304	    const cdoc = ref.current?.contentDocument;
305	    [60, 200, 500, 1200].forEach((ms) => window.setTimeout(measure, ms));
306	    observerRef.current?.disconnect();
307	    observerRef.current = null;
308	    if (cdoc?.body && typeof ResizeObserver !== "undefined") {
309	      const ro = new ResizeObserver(() => measure());
310	      ro.observe(cdoc.body);
311	      observerRef.current = ro;
312	    }
313	    cdoc?.querySelectorAll("img").forEach((img) => {
314	      if (!img.complete) img.addEventListener("load", measure, { once: true });
315	    });
316	  }, [measure]);
317	
318	  // Render the body from a blob: URL rather than `srcDoc`. A `sandbox=""` srcdoc
319	  // frame loads as `about:srcdoc`, which our strict CSP `frame-src` refuses
320	  // ("This content is blocked…"). A blob: URL is a real same-origin URL that
321	  // `frame-src blob:` matches, so the frame loads; it still inherits the app CSP
322	  // (img-src https: lets email images through, scripts stay blocked) and stays
323	  // fully sandboxed. Revoked when the body changes / unmounts.
324	  const [bodyUrl, setBodyUrl] = useState<string | null>(null);
325	  useEffect(() => {
326	    if (!doc) {
327	      setBodyUrl(null);
328	      return;
329	    }
330	    const url = URL.createObjectURL(new Blob([doc], { type: "text/html" }));
331	    setBodyUrl(url);
332	    return () => URL.revokeObjectURL(url);
333	  }, [doc]);
334	
335	  if (doc && bodyUrl) {
336	    return (
337	      <iframe
338	        ref={ref}
339	        // allow-same-origin lets the PARENT read contentDocument to auto-size the
340	        // frame; allow-scripts is deliberately omitted so sender scripts never run.
341	        sandbox="allow-same-origin"
342	        src={bodyUrl}
343	        title="Message content"
344	        onLoad={handleLoad}
345	        scrolling="no"
346	        className="w-full rounded-xl border border-white/[0.06] bg-white"
347	        style={{ height, minHeight: MIN_BODY_HEIGHT }}
348	      />
349	    );
350	  }
351	
352	  if (text && text.trim()) {
353	    return (
354	      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
355	        {text}
356	      </pre>
357	    );
358	  }
359	
360	  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
361	}
