281	/** Bucket a (newest-first) list of messages into day groups, preserving order. */
282	function groupByDay(messages: MessageSummary[]): { label: string; items: MessageSummary[] }[] {
283	  const groups: { label: string; items: MessageSummary[] }[] = [];
284	  let current: { label: string; items: MessageSummary[] } | null = null;
285	  for (const m of messages) {
286	    const label = dayLabel(m.date);
287	    if (!current || current.label !== label) {
288	      current = { label, items: [] };
289	      groups.push(current);
290	    }
291	    current.items.push(m);
292	  }
293	  return groups;
294	}
