/** True when the live script on the server is one we generated. */
export function isNxeonSieve(scriptDesc: string): boolean {
  return scriptDesc.trim() === NXEON_SIEVE_DESC;
}

// ---------------------------------------------------------------------------
// Blocked-sender filter (webmail "Block sender")
// ---------------------------------------------------------------------------
//
// A SEPARATE managed script from the auto-reply/forwarding one above, on
// purpose. Mailcow keeps at most ONE active filter per (mailbox, filter_type):
// the auto-reply/forwarding script owns `prefilter`, so blocked senders MUST use
// a different type or enabling one would silently disable the other. `postfilter`
// (Dovecot `sieve_after`) is a distinct type, so the two coexist. It runs after
// the mailbox's own script, which is fine — filing a known spammer to Junk does
// not need to pre-empt anything the customer set up, and there is no portal UI
// that files inbound mail elsewhere first. (One edge case: forwarding WITHOUT
// "keep a copy" ends the prefilter with `stop;`, so the postfilter — and thus the
// block — won't run for that mailbox. Documented, not silently wrong.)
//
// The whole blocklist lives in ONE script so it can be read back and extended:
// `parseBlockedSenders` recovers the list from the marker line, `blockSender`
// appends, and the script is rebuilt and re-pushed via the SAME Mailcow filter
// helpers (mcAddFilter/mcEditFilter) the auto-reply path uses.

/** `script_desc` tagging the blocked-senders filter as ours (never touch others). */
export const NXEON_BLOCK_DESC = "Nxeon blocked senders (managed — do not edit)";

/** Blocked senders run as a `postfilter` so they never fight the prefilter above. */
export const NXEON_BLOCK_TYPE = "postfilter" as const;

/** Machine-readable marker carrying the blocklist so it can be read back + extended. */
export const MARK_BLOCKED = "# nxeon:blocked";

/** Hard cap so a runaway block script can't grow without bound. */
export const MAX_BLOCKED_SENDERS = 500;

/** True when a live filter is our managed blocked-senders script. */
export function isNxeonBlockSieve(scriptDesc: string): boolean {
  return scriptDesc.trim() === NXEON_BLOCK_DESC;
}

/**
 * Recover the blocklist from a previously-generated block script's marker line,
 * so a new block can be appended without re-parsing sieve statements. Returns a
 * de-duplicated, lower-cased list. Unknown/empty scripts yield [].
 */
export function parseBlockedSenders(scriptData: string): string[] {
  for (const line of scriptData.split(/\r?\n/)) {
    const t = line.trim();
    if (t.startsWith(MARK_BLOCKED)) {
      const rest = t.slice(MARK_BLOCKED.length);
      return [...new Set(rest.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean))];
    }
  }
  return [];
}

/**
 * Compile a blocked-senders sieve script that files mail from any listed address
 * straight into `junkFolder` (resolved by the caller from the mailbox's real
 * folder list) and stops. Returns "" when the list is empty, so the caller can
 * DELETE the managed filter and unblocking everyone really removes it.
 */
export function buildBlockSenderSieve(addresses: string[], junkFolder: string): string {
  const clean = [...new Set(addresses.map((a) => a.trim().toLowerCase()).filter(Boolean))].slice(
    0,
    MAX_BLOCKED_SENDERS,
  );
  if (clean.length === 0) return "";

  const header = [
    "# Generated by Nxeon from your blocked senders. Changes here are overwritten.",
    `${MARK_BLOCKED} ${clean.join(", ")}`,
  ];
  // One `address :all :is "from"` test per blocked address, OR-ed together.
  const tests = clean.map((a) => `  address :all :is "from" ${sq(a)}`).join(",\r\n");
  const body = [
    'require ["fileinto"];',
    "",
    "if anyof (",
    tests,
    ")",
    "{",
    `  fileinto ${sq(junkFolder)};`,
    "  stop;",
    "}",
  ];

  return [...header, "", ...body].join("\r\n").concat("\r\n");
}

