// ---------------------------------------------------------------------------
// Spam controls: mark spam / not spam / block sender
// ---------------------------------------------------------------------------
//
// TRAINING — read this before assuming these "train the filter":
//
//   `markSpam`/`markNotSpam` reliably MOVE the message (to Junk / back to Inbox).
//   That move is ALSO the training signal — but only when the mail HOST is
//   configured for it. Mailcow ships a default Dovecot `imap_sieve` "antispam"
//   integration that runs `rspamc learn_spam` when a message is copied INTO the
//   Junk folder and `rspamc learn_ham` when one is moved OUT of it. When that
//   host config is present (the Mailcow default), these moves train Rspamd's
//   Bayes classifier as a side effect — no extra call from us.
//
//   The app CANNOT force or verify that learning itself: the Rspamd controller
//   (:11334) is not reachable from this host and there is no learn endpoint on
//   Mailcow's REST API. So this code guarantees the MOVE (immediate, visible
//   benefit); Bayes autolearn is a host-side property we neither toggle nor
//   claim. If an operator has disabled the imap_sieve antispam hooks, marking
//   still files mail correctly, it just won't teach the classifier — that is a
//   Mailcow host setting (see the admin Junk-threshold card notes), not a bug
//   here. Do not add a comment or toast that promises "trained" — we can't.

/** Resolve the IMAP path of a role folder (junk/inbox/...) with a fallback. */
async function resolveFolderPath(client: ImapFlow, role: MailFolderRole, fallback: string): Promise<string> {
  try {
    const list = await client.list();
    const f = list.find((x) => folderRole(x.path, x.specialUse) === role);
    if (f) return f.path;
  } catch {
    /* fall back to the conventional name */
  }
  return fallback;
}

/**
 * Mark a message as spam: MOVE it from its current folder to Junk. See the
 * training note above — the move is also what trains Bayes when the mail host's
 * imap_sieve antispam hooks are enabled (Mailcow default); we can't force that.
 * No-op (and no error) if the message is already in Junk.
 */
export async function markSpam(fromFolder: string, uid: number, mailboxAddress?: string): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:spam:${user.id}`, { max: 120, windowMs: 60 * 1000 });

  await withImap(cred, async (client) => {
    const junkPath = await resolveFolderPath(client, "junk", "Junk");
    // Already spam — nothing to do (and moving onto itself would error).
    if (folderRole(fromFolder) === "junk" || fromFolder === junkPath) return;
    const lock = await client.getMailboxLock(fromFolder);
    try {
      await client.messageMove(String(uid), junkPath, { uid: true });
    } finally {
      lock.release();
    }
  });
}

/**
 * Mark a message as NOT spam: MOVE it from Junk back to Inbox. The move trains
 * Rspamd as ham when the host's imap_sieve antispam hooks are enabled (Mailcow
 * default) — same caveat as `markSpam`.
 */
export async function markNotSpam(fromFolder: string, uid: number, mailboxAddress?: string): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:spam:${user.id}`, { max: 120, windowMs: 60 * 1000 });

  await withImap(cred, async (client) => {
    const inboxPath = await resolveFolderPath(client, "inbox", "INBOX");
    if (fromFolder === inboxPath) return; // already in the inbox
    const lock = await client.getMailboxLock(fromFolder);
    try {
      await client.messageMove(String(uid), inboxPath, { uid: true });
    } finally {
      lock.release();
    }
  });
}

/**
 * Block a sender: add their address to the mailbox's managed blocked-senders
 * sieve filter so FUTURE mail from them is filed straight to Junk. Reuses the
 * existing Mailcow sieve helpers (mcAddFilter/mcEditFilter) and runs as a
 * `postfilter`, separate from the auto-reply/forwarding `prefilter`, so the two
 * never disable each other (see lib/mail/sieve.ts).
 *
 * Returns a friendly `{ ok, error }` — a Mailcow/IMAP hiccup never throws out to
 * the mailbox view.
 */
export async function blockSender(
  senderAddress: string,
  mailboxAddress?: string,
): Promise<{ ok: boolean; error?: string }> {
  let ctx: Awaited<ReturnType<typeof resolveMailbox>>;
  try {
    ctx = await resolveMailbox(mailboxAddress);
  } catch (e) {
    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 200) };
  }
  const { user, cred, address, subscription } = ctx;

  const gate = checkRateLimit(`mail:block:${user.id}`, { max: 30, windowMs: 60 * 1000 });
  if (!gate.ok) return { ok: false, error: `Too many requests — please wait ${gate.retryAfterSec}s and try again.` };

  const target = (senderAddress || "").trim().toLowerCase();
  if (!target) return { ok: false, error: "There's no sender address to block." };
  if (!EMAIL_RE.test(target) || target.length > 254) {
    return { ok: false, error: "That doesn't look like a valid email address." };
  }
  if (target === address.toLowerCase()) return { ok: false, error: "You can't block your own address." };

  if (!mailcowConfigured()) return { ok: false, error: "The mail server isn't configured yet — blocking is unavailable." };
  if (subscription.status === "CANCELLED") return { ok: false, error: "This subscription is cancelled." };

  try {
    // Resolve the mailbox's real Junk path so `fileinto` targets the folder that
    // actually exists (defaults to "Junk" on Mailcow/Dovecot).
    const junkPath = await withImap(cred, (client) => resolveFolderPath(client, "junk", "Junk"));

    // Read the current managed block filter (if any) and extend its list.
    const existing = (await mcListFilters(address)).filter((f) => isNxeonBlockSieve(f.scriptDesc));
    const current = existing[0] ? parseBlockedSenders(existing[0].scriptData) : [];
    if (current.includes(target)) return { ok: true }; // already blocked — idempotent
    if (current.length >= MAX_BLOCKED_SENDERS) {
      return { ok: false, error: `You've reached the ${MAX_BLOCKED_SENDERS}-sender block limit.` };
    }

    const script = buildBlockSenderSieve([...current, target], junkPath);
    const [keep, ...duplicates] = existing;
    // Clean up any duplicate managed filters left by an interrupted save.
    for (const f of duplicates) await mcDeleteFilter(f.id);

    if (keep) {
      await mcEditFilter(keep.id, {
        scriptDesc: NXEON_BLOCK_DESC,
        scriptData: script,
        filterType: NXEON_BLOCK_TYPE,
        active: true,
      });
    } else {
      await mcAddFilter({
        address,
        scriptDesc: NXEON_BLOCK_DESC,
        scriptData: script,
        filterType: NXEON_BLOCK_TYPE,
        active: true,
      });
    }
  } catch (e) {
    return { ok: false, error: `Couldn't apply the block on the mail server: ${String((e as Error)?.message ?? e).replace(/\s+/g, " ").slice(0, 180)}` };
  }

  await db.auditLog
    .create({ data: { userId: user.id, action: "mailbox.blockSender", detail: `${address} blocked ${target}` } })
    .catch(() => {});

  return { ok: true };
}

