// "Block sender" — file the sender's FUTURE mail to Spam via a sieve filter.
// This does not remove the current message (use Mark as spam for that); it
// returns a friendly result rather than throwing.
const doBlockSender = () => {
  if (!message) return;
  const sender = message.from.address;
  if (!sender) {
    setToast("This message has no sender address to block.");
    return;
  }
  setToast(`Blocking ${sender}…`);
  void blockSender(sender, activeAddress)
    .then((res) => {
      if (res && res.ok === false) {
        setToast(res.error || "Couldn't block that sender.");
        return;
      }
      setToast(`Blocked ${sender}. Future mail from them goes to Spam.`);
    })
    .catch(() => setToast("Couldn't block that sender. Try again in a moment."));
};

