// ---------------------------------------------------------------------------
// Junk threshold policy
// ---------------------------------------------------------------------------
//
// HONEST SCOPE — read before assuming this "applies" a threshold to Rspamd:
//
//   Mailcow's REST API (the surface lib/mailcow.ts uses) exposes NO per-mailbox
//   or per-domain spam-score field: the mailbox object returned by
//   `GET /get/mailbox/all` carries no `spam_score` (verified against the live
//   server), and there is no verified endpoint to set one. So this control does
//   NOT push a score to the mail server — doing so blindly would be the silent
//   "Saved" lie this codebase keeps having to undo.
//
//   What it DOES: record the platform's chosen junk thresholds as a durable
//   policy (the Setting store), so the numbers an operator decided on are kept in
//   one auditable place, and the admin card renders the EXACT Mailcow UI / host
//   steps to apply them (pre-filled with these values). Applying the score is a
//   Mailcow host action (SSH / Mailcow UI), which the app can't perform — the
//   card says so plainly.

export const JUNK_LOW_KEY = "mail.junk.lowspam";
export const JUNK_HIGH_KEY = "mail.junk.highspam";

// Rspamd's out-of-the-box defaults: add-header (soft "spam") around 6, reject
// around 15. Lowering these is what makes the filter stricter.
export const JUNK_LOW_DEFAULT = 6;
export const JUNK_HIGH_DEFAULT = 15;

export type JunkThreshold = { low: number; high: number };

/** Read the recorded junk-threshold policy (platform-gated). */
export async function getJunkThreshold(): Promise<JunkThreshold> {
  await requireArea("platform");
  const low = await getSettingInt(JUNK_LOW_KEY, JUNK_LOW_DEFAULT);
  const high = await getSettingInt(JUNK_HIGH_KEY, JUNK_HIGH_DEFAULT);
  return { low, high };
}

/**
 * Record a stricter junk-threshold policy. Validates and persists only — see the
 * scope note above for why this does not itself push to Mailcow.
 */
export async function setJunkThreshold(
  input: { low: number; high: number },
): Promise<{ ok: boolean; error?: string; value?: JunkThreshold }> {
  const user = await requireArea("platform");

  const low = Math.round(Number(input.low));
  const high = Math.round(Number(input.high));
  if (!Number.isFinite(low) || !Number.isFinite(high)) {
    return { ok: false, error: "Enter numeric spam scores." };
  }
  if (low < 1 || high < 1 || low > 50 || high > 50) {
    return { ok: false, error: "Scores must be between 1 and 50." };
  }
  if (low >= high) {
    return { ok: false, error: "The low (junk) score must be below the high (reject) score." };
  }

  await setSetting(JUNK_LOW_KEY, String(low));
  await setSetting(JUNK_HIGH_KEY, String(high));

  await db.auditLog
    .create({ data: { userId: user.id, action: "mail.junkThreshold", detail: `low=${low} high=${high}` } })
    .catch(() => {});

  return { ok: true, value: { low, high } };
}

