/**
 * Junk-threshold policy card.
 *
 * IMPORTANT (kept honest on purpose): Mailcow's REST API exposes no spam-score
 * field, so this control RECORDS the chosen thresholds and shows the exact
 * Mailcow/host steps to apply them — it does not silently pretend to push a score
 * the API can't set. See lib/actions-mail-admin.ts for the full rationale.
 */
function JunkThresholdCard() {
  const [low, setLow] = useState<number | "">("");
  const [high, setHigh] = useState<number | "">("");
  const [loaded, setLoaded] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<{ tone: "green" | "red"; text: string } | null>(null);

  useEffect(() => {
    getJunkThreshold()
      .then((t) => {
        setLow(t.low);
        setHigh(t.high);
      })
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, []);

  const save = async () => {
    setSaving(true);
    setMsg(null);
    try {
      const res = await setJunkThreshold({ low: Number(low), high: Number(high) });
      if (res.ok) {
        if (res.value) {
          setLow(res.value.low);
          setHigh(res.value.high);
        }
        setMsg({ tone: "green", text: "Threshold policy saved. Apply it on the mail host using the steps below." });
      } else {
        setMsg({ tone: "red", text: res.error || "Couldn't save." });
      }
    } catch {
      setMsg({ tone: "red", text: "Couldn't save — please try again." });
    } finally {
      setSaving(false);
    }
  };

  const lowVal = low === "" ? "<low>" : String(low);
  const highVal = high === "" ? "<high>" : String(high);

  return (
    <div className="card">
      <div className="flex flex-wrap items-center gap-2">
        <h2 className="font-semibold text-white">Junk threshold</h2>
        <Badge tone="violet">policy</Badge>
      </div>
      <p className="mt-2 text-sm text-slate-300">
        Set a stricter default for how aggressively Rspamd files spam. The{" "}
        <span className="font-mono">low</span> score is where a message is treated as junk (soft
        spam / add-header); the <span className="font-mono">high</span> score is where it is
        rejected outright. Lower numbers = stricter. Rspamd ships with roughly{" "}
        <span className="font-mono">6</span> / <span className="font-mono">15</span>.
      </p>

      <div className="mt-4 flex flex-wrap items-end gap-4">
        <label className="flex flex-col gap-1">
          <span className="section-label">Low (junk) score</span>
          <input
            type="number"
            min={1}
            max={50}
            value={low}
            disabled={!loaded || saving}
            onChange={(e) => setLow(e.target.value === "" ? "" : Number(e.target.value))}
            className="w-28 rounded-xl border border-white/10 bg-navy-900/80 px-3 py-2 text-sm text-slate-100 outline-none focus:border-brand-400/60"
          />
        </label>
        <label className="flex flex-col gap-1">
          <span className="section-label">High (reject) score</span>
          <input
            type="number"
            min={1}
            max={50}
            value={high}
            disabled={!loaded || saving}
            onChange={(e) => setHigh(e.target.value === "" ? "" : Number(e.target.value))}
            className="w-28 rounded-xl border border-white/10 bg-navy-900/80 px-3 py-2 text-sm text-slate-100 outline-none focus:border-brand-400/60"
          />
        </label>
        <button className="btn-primary py-2" onClick={save} disabled={!loaded || saving}>
          {saving ? "Saving…" : "Save policy"}
        </button>
      </div>

      {msg && (
        <p className={`mt-3 text-sm ${msg.tone === "green" ? "text-emerald-400" : "text-red-400"}`}>
          {msg.text}
        </p>
      )}

      <div className="mt-4 rounded-xl border border-white/[0.06] bg-white/[0.02] p-4 text-sm text-slate-300">
        <p className="font-semibold text-white">Applying it on the mail host</p>
        <p className="mt-1 text-slate-400">
          Mailcow&apos;s API has no spam-score field, so the numbers above are recorded here but must
          be applied on the mail server (10.20.0.10). Two ways:
        </p>
        <p className="mt-3 font-medium text-slate-200">Global default (SSH to the Mailcow host)</p>
        <pre className="mt-1 overflow-x-auto rounded-lg bg-navy-950/70 p-3 text-[12px] leading-relaxed text-slate-300">
{`# in the mailcow-dockerized directory:
cat > data/conf/rspamd/override.d/actions.conf <<'EOF'
add_header = ${lowVal};
reject = ${highVal};
EOF
docker compose restart rspamd-mailcow`}
        </pre>
        <p className="mt-3 font-medium text-slate-200">Per-mailbox (Mailcow admin UI)</p>
        <p className="mt-1 text-slate-400">
          Configuration → Mail Setup → Mailboxes → edit a mailbox → set its spam-filter Low /
          High scores to <span className="font-mono">{lowVal}</span> /{" "}
          <span className="font-mono">{highVal}</span>.
        </p>
      </div>
    </div>
  );
}

